7.query:
timeseries v = avg(dt.host.cpu.usage), by: {dt.entity.host}
| fieldsAdd host = entityName(dt.entity.host)
| fieldsRemove dt.entity.host

8.query:
timeseries v = avg(dt.host.memory.usage), by: {dt.entity.host}
| fieldsAdd host = entityName(dt.entity.host)
| fieldsRemove dt.entity.host

9.query:
timeseries v = max(dt.host.disk.used.percent), by: {dt.entity.host}
| fieldsAdd host = entityName(dt.entity.host)
| fieldsRemove dt.entity.host

11.query:
timeseries v = avg(dt.host.cpu.load5m), by: {dt.entity.host}
| fieldsAdd host = entityName(dt.entity.host)
| fieldsRemove dt.entity.host

12.query:
timeseries { cpu = avg(dt.host.cpu.usage), mem = avg(dt.host.memory.usage), disk = max(dt.host.disk.used.percent) }, by: {dt.entity.host}
| fields Host = entityName(dt.entity.host), `CPU %` = arrayAvg(cpu), `Memory %` = arrayAvg(mem), `Max disk %` = arrayMax(disk)
| sort `CPU %` desc

